window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-b71fc6602da7855c"]={"versions": [{"id": "FIG-b71fc6602da7855c", "releases": ["R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikationsbereichs-Modellierung im Metamodell der AUTOSAR Standardisierungs-Templates (TPS_StandardizationTemplate). Es beschreibt die Struktur zur Abgrenzung und Zuordnung von Spezifikationsumfängen (<code>SpecificationScope</code>) über Dokumentenebenen (<code>SpecificationDocumentScope</code>) bis hin zu einzelnen Dokumentelementen (<code>DocumentElementScope</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><code>SpecificationScope</code>: Wurzelentität des Spezifikationsumfangs, besitzt eine Kompositionsbeziehung <code>+specificationDocumentScope</code> mit der Kardinalität <code>0..*</code> zu <code>SpecificationDocumentScope</code>.\n</li><li><code>SpecificationDocumentScope</code>: Repräsentiert den Geltungsbereich auf Dokumentenebene. Besitzt eine Kompositionsbeziehung <code>+documentElementScope</code> mit Kardinalität <code>0..*</code> zu <code>DocumentElementScope</code>. Spezialisiert <code>CommonPatterns::SpecElementScope</code>.\n</li><li><code>DocumentElementScope</code>: Repräsentiert den Geltungsbereich auf Ebene einzelner Dokumentelemente. Spezialisiert ebenfalls <code>CommonPatterns::SpecElementScope</code>.\n</li><li><code>CommonPatterns::SpecElementScope</code>: Abstrakte Basisklasse, erbt von <code>Identifiable</code> bzw. <code>CommonPatterns::SpecElementReference</code>. Enthält das Attribut <code>+ inScope :Boolean [0..1]</code>.\n</li><li><code>CommonPatterns::SpecElementReference</code>: Spezialisierung von <code>Identifiable</code>, definiert das Attribut <code>+ alternativeName :String [0..1]</code>.\n</li><li><code>Identifiable</code>: Abstrakte AUTOSAR-Basisklasse für identifizierbare Elemente.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell-Strukturdiagramm; es stellt keine dynamischen Interaktionen oder Laufzeitsequenzen dar. Die Instanziierung erfolgt typischerweise im Rahmen der Modellierung von Standardisierungsdokumenten hierarchisch von <code>SpecificationScope</code> über <code>SpecificationDocumentScope</code> zu <code>DocumentElementScope</code>.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Relevant für Autoren und Werkzeugentwickler im Bereich der AUTOSAR-Standardisierungstemplates. Die Modellierung erlaubt das selektive Ein- oder Ausschließen von Spezifikationsinhalten (<code>inScope</code>) sowohl auf Dokumentenebene als auch granular auf Elementebene. Attribute <code>inScope</code> und <code>alternativeName</code> sind optional (<code>[0..1]</code>). Die Aggregationen zu den untergeordneten Scopes sind als Kompositionen ausgeführt und besitzen die Multiplizität <code>0..*</code>.</p>"}, {"id": "FIG-89ce9f5b4d8264a3", "releases": ["R18-10_R4.4.0_R1.5.0", "R19-11", "R20-11", "R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikationsbereichs-Modellierung im Metamodell der AUTOSAR Standardisierungs-Templates (TPS_StandardizationTemplate). Es beschreibt die Struktur zur Abgrenzung und Zuordnung von Spezifikationsumfängen (<code>SpecificationScope</code>) über Dokumentenebenen (<code>SpecificationDocumentScope</code>) bis hin zu einzelnen Dokumentelementen (<code>DocumentElementScope</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><code>SpecificationScope</code>: Wurzelentität des Spezifikationsumfangs, besitzt eine Kompositionsbeziehung <code>+specificationDocumentScope</code> mit der Kardinalität <code>0..*</code> zu <code>SpecificationDocumentScope</code>.\n</li><li><code>SpecificationDocumentScope</code>: Repräsentiert den Geltungsbereich auf Dokumentenebene. Besitzt eine Kompositionsbeziehung <code>+documentElementScope</code> mit Kardinalität <code>0..*</code> zu <code>DocumentElementScope</code>. Spezialisiert <code>CommonPatterns::SpecElementScope</code>.\n</li><li><code>DocumentElementScope</code>: Repräsentiert den Geltungsbereich auf Ebene einzelner Dokumentelemente. Spezialisiert ebenfalls <code>CommonPatterns::SpecElementScope</code>.\n</li><li><code>CommonPatterns::SpecElementScope</code>: Abstrakte Basisklasse, erbt von <code>Identifiable</code> bzw. <code>CommonPatterns::SpecElementReference</code>. Enthält das Attribut <code>+ inScope: Boolean [0..1]</code>.\n</li><li><code>CommonPatterns::SpecElementReference</code>: Spezialisierung von <code>Identifiable</code>, definiert das Attribut <code>+ alternativeName: String [0..1]</code>.\n</li><li><code>Identifiable</code>: Abstrakte AUTOSAR-Basisklasse für identifizierbare Elemente.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell-Strukturdiagramm; es stellt keine dynamischen Interaktionen oder Laufzeitsequenzen dar. Die Instanziierung erfolgt typischerweise im Rahmen der Modellierung von Standardisierungsdokumenten hierarchisch von <code>SpecificationScope</code> über <code>SpecificationDocumentScope</code> zu <code>DocumentElementScope</code>.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Relevant für Autoren und Werkzeugentwickler im Bereich der AUTOSAR-Standardisierungstemplates. Die Modellierung erlaubt das selektive Ein- oder Ausschließen von Spezifikationsinhalten (<code>inScope</code>) sowohl auf Dokumentenebene als auch granular auf Elementebene. Attribute <code>inScope</code> und <code>alternativeName</code> sind optional (<code>[0..1]</code>). Die Aggregationen zu den untergeordneten Scopes sind als Kompositionen ausgeführt und besitzen die Multiplizität <code>0..*</code>.</p>"}, {"id": "FIG-117688f6b9431bec", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikationsbereichs-Modellierung im Metamodell der AUTOSAR Standardisierungs-Templates (TPS_StandardizationTemplate). Es beschreibt die Struktur zur Abgrenzung und Zuordnung von Spezifikationsumfängen (<code>SpecificationScope</code>) über Dokumentenebenen (<code>SpecificationDocumentScope</code>) bis hin zu einzelnen Dokumentelementen (<code>DocumentElementScope</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><code>SpecificationScope</code>: Wurzelentität des Spezifikationsumfangs, besitzt eine Kompositionsbeziehung <code>+specificationDocumentScope</code> mit der Kardinalität <code>0..*</code> zu <code>SpecificationDocumentScope</code>.\n</li><li><code>SpecificationDocumentScope</code>: Repräsentiert den Geltungsbereich auf Dokumentenebene. Besitzt eine Kompositionsbeziehung <code>+documentElementScope</code> mit Kardinalität <code>0..*</code> zu <code>DocumentElementScope</code>. Spezialisiert <code>CommonPatterns::SpecElementScope</code>.\n</li><li><code>DocumentElementScope</code>: Repräsentiert den Geltungsbereich auf Ebene einzelner Dokumentelemente. Spezialisiert ebenfalls <code>CommonPatterns::SpecElementScope</code>.\n</li><li><code>CommonPatterns::SpecElementScope</code>: Abstrakte Basisklasse, erbt von <code>Identifiable</code> bzw. <code>CommonPatterns::SpecElementReference</code>. Enthält das Attribut <code>+ inScope: Boolean [0..1]</code>.\n</li><li><code>CommonPatterns::SpecElementReference</code>: Spezialisierung von <code>Identifiable</code>, definiert das Attribut <code>+ alternativeName: String [0..1]</code>.\n</li><li><code>Identifiable</code>: Abstrakte AUTOSAR-Basisklasse für identifizierbare Elemente.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell-Strukturdiagramm; es stellt keine dynamischen Interaktionen oder Laufzeitsequenzen dar. Die Instanziierung erfolgt typischerweise im Rahmen der Modellierung von Standardisierungsdokumenten hierarchisch von <code>SpecificationScope</code> über <code>SpecificationDocumentScope</code> zu <code>DocumentElementScope</code>.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Relevant für Autoren und Werkzeugentwickler im Bereich der AUTOSAR-Standardisierungstemplates. Die Modellierung erlaubt das selektive Ein- oder Ausschließen von Spezifikationsinhalten (<code>inScope</code>) sowohl auf Dokumentenebene als auch granular auf Elementebene. Attribute <code>inScope</code> und <code>alternativeName</code> sind optional (<code>[0..1]</code>). Die Aggregationen zu den untergeordneten Scopes sind als Kompositionen ausgeführt und besitzen die Multiplizität <code>0..*</code>.</p>"}], "trans": [{"from": "FIG-b71fc6602da7855c", "to": "FIG-89ce9f5b4d8264a3", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li><code>CommonPatterns::SpecElementReference</code>: Formatierung des Attributs angepasst von <code>+ alternativeName :String [0..1]</code> zu <code>+ alternativeName: String [0..1]</code> (Entfernung des Leerzeichens vor dem Doppelpunkt).\n</li><li><code>CommonPatterns::SpecElementScope</code>: Formatierung des Attributs angepasst von <code>+ inScope :Boolean [0..1]</code> zu <code>+ inScope: Boolean [0..1]</code> (Entfernung des Leerzeichens vor dem Doppelpunkt).\n</li></ul>"}, {"from": "FIG-89ce9f5b4d8264a3", "to": "FIG-117688f6b9431bec", "fr": "R21-11", "tr": "R22-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
